class TestBinaryFiles:
    def test_binary_entries_do_not_crash_or_count(self, tmp_path: Path):
        r = tmp_path / "binrepo"
        r.mkdir()
        _git(r, "init", "-q")
        (r / "blob.bin").write_bytes(b"\x00\x01\x02binary\x00")
        _commit(r, "dave", "add binary", 1)
        out = run_cli(r, "--churn")
        assert out.splitlines() == ["churn:", "dave\t0\t0"]


